INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63357492', 63357492, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Manajemen Konstruksi Pelaksanaan Pembangunan Kab. Nias Selatan (RSU Kelas D Pratama Kab. Nias Selatan)', 'Jasa Konsultansi', 'Seleksi', 'Sumatera Utara, Nias Selatan (Kab.)', 3935000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PT, @ 3935000000 )', '1. Manajemen Konstruksi ( 1, PT, @ 3935000000 ); Manajemen Konstruksi Pelaksanaan Pembangunan Kab. Nias Selatan (RSU Kelas D Pratama Kab. Nias Selatan) Ruang lingkup pekerjaan Manajemen Konstruksi meliputi pendampingan dan pengendalian pelaksanaan pekerjaan konstruksi terintegrasi (design and build) pembangunan rumah sakit dalam rangka peningkatan kelas rumah sakit dari Kelas D menjadi Kelas C. Pekerjaan mencakup pengendalian mutu, waktu, biaya, dan keselamatan dan kesehatan kerja (K3), koordinasi antar pihak terkait, evaluasi dan verifikasi dokumen desain dan pelaksanaan, monitoring dan pelaporan progres pekerjaan, pengendalian perubahan pekerjaan, serta pendampingan hingga serah terima pekerjaan sesuai ketentuan peraturan perundang-undangan di bidang jasa konstruksi.', 'Spesifikasi pekerjaan Manajemen Konstruksi meliputi penyediaan jasa keahlian profesional untuk mendukung pengendalian pelaksanaan pekerjaan konstruksi terintegrasi (design and build) pembangunan rumah sakit. Jasa yang diberikan mencakup pengendalian mutu, waktu, biaya, dan keselamatan dan kesehatan kerja (K3), koordinasi antar pihak terkait, serta evaluasi dan verifikasi dokumen desain dan pelaksanaan. Pelaksanaan pekerjaan dilakukan sesuai standar teknis bangunan rumah sakit, ketentuan peraturan perundang-undangan di bidang jasa konstruksi, dan persyaratan kontrak, dengan rincian teknis lebih lanjut ditetapkan dalam Kerangka Acuan Kerja (KAK) dan dokumen pemilihan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 930136);
