INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63358304', 63358304, 'analyze_legacy', 'Kab. Batang', 'kabkota', 'DINAS PEMBERDAYAAN PEREMPUAN PERLINDUNGAN ANAK PENGENDALIAN PENDUDUK DAN KELUARGA BERENCANA', 'Belanja Makanan dan Minuman Rapat - Bidang KB ( Peningkatan Kesertaan Penggunaan Metode Kontrasepsi Jangka Panjang (MKJP) )', 'Barang', 'E-Purchasing', 'Jawa Tengah, Batang (Kab.)', 423320000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Makanan dan Minuman Rapat - Bidang KB ( Peningkatan Kesertaan Penggunaan Metode Kontrasepsi Jangka Panjang (MKJP) )', 'Belanja Makanan dan Minuman Rapat - Bidang KB ( Peningkatan Kesertaan Penggunaan Metode Kontrasepsi Jangka Panjang (MKJP) )', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 932173);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63402141', 63402141, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Modal Alat Ukur GNSS', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 828892500, 'March 2026', 'APBD', 1, 1, '5 Unit', 'Uraian pekerjaan ini meliputi kegiatan pengadaan, penyediaan, pengiriman, instalasi, serta penyerahan Alat Ukur GNSS (Global Navigation Satellite System) yang digunakan untuk mendukung kegiatan pengukuran dan pemetaan geospasial, survei lapangan, penentuan koordinat, serta pengumpulan data spasial secara akurat dan andal. Alat ukur GNSS yang disediakan harus memiliki tingkat ketelitian tinggi, teknologi mutakhir, serta mampu beroperasi secara optimal pada berbagai kondisi lapangan. Perangkat yang disediakan wajib dalam kondisi baru, asli pabrikan, dan memenuhi spesifikasi teknis yang telah ditetapkan. Ruang Lingkup Pekerjaan meliputi: Pengadaan alat ukur GNSS sesuai jumlah dan spesifikasi teknis yang ditetapkan dalam kontrak. Menjamin alat GNSS dalam kondisi baru, bukan barang bekas atau rekondisi, serta bergaransi resmi pabrikan. Penyediaan perangkat GNSS lengkap beserta aksesorinya, termasuk perangkat keras, perangkat lunak, dan kelengkapan standar pabrikan. Pengiriman alat GNSS ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) atau Pejabat Pengadaan. Pelaksanaan instalasi awal dan konfigurasi perangkat agar siap digunakan. Pengujian fungsi dasar alat GNSS untuk memastikan kinerja dan akurasi pengukuran. Pemberian pelatihan singkat atau penjelasan teknis penggunaan alat kepada pengguna (apabila dipersyaratkan). Penggantian unit apabila ditemukan kerusakan, cacat produksi, atau ketidaksesuaian spesifikasi pada saat pemeriksaan. Pelaksanaan pemeriksaan dan serah terima alat yang dituangkan dalam Berita Acara Serah Terima (BAST) sesuai ketentuan yang berlaku. Dengan terlaksananya pekerjaan ini, diharapkan ketersediaan alat ukur GNSS dapat mendukung pelaksanaan kegiatan pengukuran dan pemetaan secara lebih akurat, efisien, dan profesional.', 'Pengadaan Alat Ukur GNSS 1. Nama Pekerjaan Pengadaan Alat Ukur GNSS (Global Navigation Satellite System) 2. Jenis Pekerjaan Pengadaan Barang Peralatan Survei dan Pemetaan 3. Maksud dan Tujuan Menyediakan alat ukur GNSS yang andal dan akurat untuk mendukung kegiatan pengukuran koordinat, pemetaan geospasial, survei lapangan, serta pengumpulan data spasial secara presisi dan efisien. 4. Ruang Lingkup Pekerjaan Ruang lingkup pekerjaan meliputi: Pengadaan alat ukur GNSS sesuai jumlah dan spesifikasi teknis. Penyediaan perangkat GNSS lengkap beserta aksesori pendukung. Pengiriman alat GNSS ke lokasi yang ditentukan. Instalasi dan konfigurasi awal perangkat. Pengujian fungsi dan akurasi dasar alat GNSS. Penjelasan/pelatihan singkat penggunaan alat (jika dipersyaratkan). Serah terima barang sesuai ketentuan yang berlaku. 5. Spesifikasi Teknis Alat GNSS Jenis alat: GNSS Geodetik / GNSS Survey Grade Sistem satelit: GPS, GLONASS, Galileo, BeiDou atau setara Metode pengukuran: Static, Rapid Static, RTK, dan/atau Network RTK Ketelitian posisi horizontal: ≤ ±10 mm + 1 ppm Ketelitian posisi vertikal: ≤ ±20 mm + 1 ppm Receiver multi-frequency Antena GNSS berpresisi tinggi Sistem komunikasi: radio internal/eksternal dan/atau jaringan seluler Penyimpanan data internal dan eksternal 6. Perangkat Lunak (Software) Software pengolahan data GNSS bawaan pabrikan Mendukung format data standar (RINEX, CSV, DXF, SHP atau setara) Kompatibel dengan sistem operasi Windows 7. Aksesori Pendukung Controller/data logger Antena GNSS Baterai dan charger Tripod/pole survei Kabel dan konektor Tas pelindung (hardcase) 8. Kondisi Barang Baru (brand new) Bukan barang bekas atau rekondisi Produk resmi pabrikan 9. Standar dan Mutu Memenuhi standar alat survei dan pemetaan Kualitas pabrikan terjamin Sertifikasi produk resmi 10. Garansi dan Layanan Purna Jual Garansi resmi pabrikan minimal 1 (satu) tahun Tersedia layanan servis dan suku cadang di Indonesia 11. Waktu Pelaksanaan Waktu pengadaan dan penyerahan sesuai jadwal dalam kontrak/SPK 12. Pengujian dan Pemeriksaan Pemeriksaan fisik kelengkapan barang Uji fungsi pengukuran dasar Verifikasi kesesuaian spesifikasi 13. Keselamatan dan Keamanan Alat dikemas dan dikirim dengan aman Menjamin alat dalam kondisi baik hingga serah terima 14. Serah Terima Pekerjaan Dilaksanakan setelah barang diterima dan dinyatakan sesuai Dibuktikan dengan Berita Acara Serah Terima (BAST)', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 932174);
