INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63424428', 63424428, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Langganan Metronet Pada Ditjen Kekayaan Intelektual - DKI Jakarta TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 140000000, 'December 2025', 'APBN - PNBP (D)', 0, 1, '8 Bulan', 'Menyediakan langganan metronet selama 8 bulan kalender', '1. Menyediakan layanan Langganan Metronet sebesar 200 Mbps dengan menyesuaikan topolologi jaringan DJKI yang menggunakan Redundant Link, sehingga dapat menghubungkan kedua gedung DJKI di Jl H.R Rasuna Said Kav 8-9 Jakarta Selatan dan Jl Daan Mogot Km 24 Tangerang Banten. 2. Menyediakan jalur koneksi Langganan Metronet dengan sistem n+1 (Secondary Link) untuk layanan koneksi Langganan Metronet dengan dukungan Multi Vlan dengan spesifikasi yang sama dengan Primary Link. Secondary link yaitu penyedia jasa harus memiliki dua jalur (POP) yang berbeda pada masing - masing koneksi di kedua Gedung DJKI. Adapun jalur ini akan berguna apabila satu jalur terganggu maka penyedia jasa akan segera mengalihkan ke jalur koneksi yang lain. 3. Primary Link dan Secondary Link Fiber Optic merupakan infrastruktur yang dimiliki penyedia jasa dan bukan milik perusahaan lain. 4. Memberikan layanan bandwidth dengan ratio CIR (Committed Information Rate) adalah 1:1 (Clear Chanel) untuk upload dan download.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 932832);
