INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63425323', 63425323, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Trans Illuminator Gel Electrophoresis', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 2647050000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 0, '1 Paket', '1. Belanja Modal Peralatan dan Mesin;', 'Alat yang digunakan untuk visualisasi DNA, RNA, atau protein setelah proses elektroforesis. Manfaat utamanya adalah kemampuannya untuk memperlihatkan band yang terbentuk pada gel, sehingga memungkinkan peneliti untuk menganalisis ukuran dan kemurnian asam nukleat atau protein. Dengan menggunakan cahaya ultraviolet, trans illuminator dapat mendeteksi fluorokrom yang digunakan dalam pewarnaan sampel, memberikan hasil yang jelas dan akurat. Alat ini sangat penting dalam aplikasi biologi molekuler, termasuk analisis genetik, pemetaan genom, dan studi ekspresi gen.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 934499);
