INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63403671', 63403671, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pekerjaan Jasa Konsultansi Badan Usaha Konstruksi Jasa Konsultan Pengawas Rehabilitasi Ruang Kerja Gedung Madiun Lantai 5', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 300366000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PKT', 'lingkup tugas pekerjaan jasa Konsultan Pengawas ini adalah melaksanakan pengawasan Ruang Kerja Gedung Madiun Lantai 5 sampai dengan tahap masa pemeliharaan pekerjaan.', 'Rincian pelaksanaan pekerjaan yang berada dalam pengendalian Konsultan Pengawas adalah sebagai berikut: a. Memeriksa dan mempelajari dokumen untuk pelaksanaan konstruksi yang akan dijadikan dasar dalam pengawasan pekerjaan di lapangan; b. Mengawasi pemakaian bahan, peralatan dan metoda pelaksanaan, serta mengawasi ketepatan waktu, atau biaya pekerjaan konstruksi secara kaidah Bangunan Cagar Budaya; c. Mengawasi pelaksanaan pekerjaan konstruksi dari segi kualitas, kuantitas, dan laju pencapaian volume/realisasi fisik Bangunan Cagar Budaya; d. Mengumpulkan data dan informasi di lapangan untuk membantu memecahkan persoalan yang terjadi selama pelaksanaan konstruksi; e. Menyelenggarakan rapat-rapat lapangan secara berkala, rapat evaluasi mingguan kemajuan prestasi pekerjaan fisik dan membuat laporan mingguan dan bulanan pekerjaan pengawasan dengan masukan hasil rapat-rapat lapangan, laporan laporan harian, mingguan dan bulanan pekerjaan konstruksi yang dibuat oleh Kontraktor Pelaksana/Pemborong; f. Melakukan pengawasan Ruang Kerja Gedung Madiun Lantai 5 supaya berfungsi dengan baik sebagai ruang kantor g. Memeriksa berita acara kemajuan pekerjaan untuk pembayaran angsuran, pemeliharaan pekerjaan, dan serah terima pertama dan kedua pekerjaan konstruksi; h. Meneliti gambar-gambar pelaksanaan (shop drawing) yang diajukan oleh Kontraktor pelaksana/Pemborong; i. Meneliti gambar-gambar yang sesuai dengan pelaksanaan (as-built drawing) sebelum serah terima pertama; j. Menyusun daftar cacat-cacat/kerusakan sebelum serah terima pertama, mengawasi perbaikannya pada masa pemeliharaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 935337);
