INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63446868', 63446868, 'analyze_legacy', 'Kab. Tabalong', 'kabkota', 'KECAMATAN TANJUNG', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Bahan Cetak', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Selatan, Tabalong (Kab.)', 5604492, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Spanduk; Spanduk; Cetak papan Informasi;', 'SPANDUK "1. Bahan (Material): -Flexi China: Ekonomis, untuk jangka pendek/acara sekolah. -Flexi Korea: Tebal & halus, cocok untuk luar ruangan (outdoor). -Albatros: Halus & tipis, khusus dalam ruangan (indoor/X-Banner). 2. Teknis DesainWarna: Wajib mode CMYK (agar warna cetak akurat). Resolusi: 100–150 DPI (untuk ukuran besar) atau 300 DPI (untuk ukuran kecil). Format: PDF, JPG, atau TIFF. 3. Finishing (Pemasangan): Mata Ayam: Lubang ring besi di pojok (untuk tali). Slongsong: Lubang untuk selipan bambu atau kayu. Lipat Press: Pinggiran rapi hanya dilem (tanpa lubang). 4. Ukuran Populer Horizontal: 2 x 1 m, 3 x 1m, atau 5 x 1m. Vertikal (X-Banner): 60 x 160 cm." Cetak Papan Informasi "1. Material Utama Outdoor (Kuat/Tahan Cuaca): ACP (Aluminium Composite Panel) atau Acrylic tebal. Indoor (Ringan/Estetik): PVC Board, Foamcore, atau Acrylic tipis. 2. Metode Cetak UV Build-up: Cetak langsung ke bahan (paling awet & tahan pudar). Sticker Vinyl: Dicetak di stiker lalu ditempel (ekonomis, wajib tambah Laminasi). 3. Ukuran & Ketebalan Ukuran Umum: A3 (29.7x42 cm), 40x60 cm, atau 60x90 cm. Ketebalan: 3mm (standar) hingga 5mm (lebih kokoh). 4. Finishing (Pemasangan) Mata Ayam/Lubang: Untuk diikat atau disekrup. Pen Iklan: Baut stainless khusus agar papan terlihat ""melayang"" (untuk Acrylic). Double Tape Foam: Untuk pemasangan praktis di dinding rata. 5. Standar Desain Resolusi: 300 DPI (biar tidak pecah). Warna: Mode CMYK (standar cetak). Font: Sans Serif (Arial/Helvetica) agar mudah dibaca cepat."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 937061);
