INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63446869', 63446869, 'analyze_legacy', 'Kab. Tabalong', 'kabkota', 'KECAMATAN TANJUNG', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Perabot Kantor', 'Barang', 'E-Purchasing', 'Kalimantan Selatan, Tabalong (Kab.)', 22026900, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Jam Dinding; Sapu Lidi Tongkat; Cangkul; Parang; Gunting Pangkas; Sarung Tangan Karet;', '1. Jam Dinding Material: Bingkai plastik ABS/Metal dengan kaca pelindung. Mesin: Quartz Movement (detik halus/sweep silent lebih disukai). Ukuran: Diameter minimal 30 cm. Fitur: Angka numerik besar yang kontras dan mudah dibaca. 2. Sapu Lidi Tongkat Material Lidi: Aren atau kelapa yang tua, kuat, dan lentur. Material Tongkat: Kayu atau bambu dengan panjang 60–90 cm. Ikatan: Lilitan kawat atau plastik yang kencang agar lidi tidak mudah lepas. Kegunaan: Pembersihan area luar ruangan (halaman/jalan). 3. Cangkul Material Mata: Baja karbon atau besi cor berkualitas tinggi. Material Gagang: Kayu keras (seperti kayu jati atau mahoni) dengan panjang ±1 meter. Ukuran Mata: Lebar sekitar 18–20 cm. Fitur: Sambungan mata dan gagang harus kokoh (menggunakan pasak). 4. Parang Material Bilah: Baja per (spring steel) yang ditempa dan tajam. Material Gagang: Kayu atau plastik tebal yang tidak licin (full tang diutamakan). Panjang Bilah: 30–50 cm. Kegunaan: Menebas semak belukar atau ranting pohon. 5. Gunting Pangkas (Pruning Shears) Material Bilah: Stainless steel atau High Carbon Steel anti karat. Material Handle: Logam dilapisi karet/ergonomis. Sistem: Bypass (untuk dahan hidup) atau Anvil (untuk dahan mati). Fitur: Pengunci keamanan (safety lock) saat tidak digunakan. 6. Sarung Tangan Karet Material: Lateks atau Nitril berkualitas tinggi. Tekstur: Permukaan telapak tangan bertekstur (anti slip). Ketebalan: Medium hingga heavy duty agar tidak mudah robek. Panjang: Menutup hingga pergelangan tangan (minimal 30 cm).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 937304);
